open(base+'/task-e058cbaf.py','w').write('''def transform(grid):
    H, W = len(grid), len(grid[0])
    sep_rows = [i for i in range(H) if len(set(grid[i])) == 1 and grid[i][0] != 0]
    sep_cols = [j for j in range(W) if len({grid[i][j] for i in range(H)}) == 1 and grid[0][j] != 0]
    bands_r = [(a, b) for a, b in zip([0] + [r + 1 for r in sep_rows], [r - 1 for r in sep_rows] + [H - 1])]
    bands_c = [(a, b) for a, b in zip([0] + [c + 1 for c in sep_cols], [c - 1 for c in sep_cols] + [W - 1])]
    bandcolor = {}
    for bi, (r0, r1) in enumerate(bands_r):
        col = 0
        for i in range(r0, r1 + 1):
            for j in range(0, bands_c[0][1] + 1):
                if grid[i][j] != 0:
                    col = grid[i][j]
        bandcolor[bi] = col
    bcols = set(bandcolor.values())
    tmpl = [(i, j) for i in range(H) for j in range(W)
            if grid[i][j] != 0 and grid[i][j] not in bcols and i not in sep_rows and j not in sep_cols]
    if not tmpl:
        return [row[:] for row in grid]
    rs = [i for i, _ in tmpl]; cs = [j for _, j in tmpl]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    shape = [[(1 if grid[i][j] != 0 else 0) for j in range(c0, c1 + 1)] for i in range(r0, r1 + 1)]
    out = [[0] * W for _ in range(H)]
    for i in sep_rows:
        out[i] = [grid[i][0]] * W
    for j in sep_cols:
        for i in range(H):
            out[i][j] = grid[0][j]
    for bi, (br0, br1) in enumerate(bands_r):
        col = bandcolor[bi]
        for (bc0, bc1) in bands_c:
            for si, row in enumerate(shape):
                for sj, v in enumerate(row):
                    if v:
                        out[br0 + si][bc0 + sj] = col
    return out
''')
